public static String classTotals(int[] amounts) {
    String s = "";
    int i = 0;
    while (i < amounts.length) {          // כיתה אחרי כיתה
        int sum = 0;
        while (amounts[i] != -1) {        // הסכומים של הכיתה
            sum = sum + amounts[i];
            i++;
        }
        i++;                              // מדלגים על -1
        s = s + sum + " ";
    }
    return s;
}

public static int gradeTotal(int[] amounts) {
    int total = 0;
    for (int i = 0; i < amounts.length; i++) {
        if (amounts[i] != -1) {
            total = total + amounts[i];
        }
    }
    return total;
}

